    def move(self) -> None:
        self.x += self.dx
        self.y += self.dy

    @property
    def get_x(self) -> int:
        return self.x

    @property
    def get_y(self) -> int:
        return self.y


n = int(input())
t = input()

motion = Motion()
for c in t:
    if c == "S":
        motion.move()
    else:
        motion.rotate()

print(f"{motion.get_x} {motion.get_y}")
